const e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Automatisez votre imprimante avec des règles SI-ALORS sûres. Désactivées par défaut ; armez chaque règle vous-même."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Aucune règle pour le moment. Ajoutez-en une ci-dessous, puis armez-la quand vous êtes prêt."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"Le moteur de règles est ACTIVÉ"}},off:{t:0,b:{t:2,i:[{t:3}],s:"Le moteur de règles est DÉSACTIVÉ"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"Activer"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"Désactiver"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"Rien ne s'exécute tant que le moteur et la règle individuelle ne sont pas tous deux activés."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"Quand une impression se termine"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"Quand l'imprimante rencontre une erreur"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"Quand un chauffage dépasse"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"Quand un chauffage descend sous"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"Enregistrer une notification"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"Exécuter une commande g-code"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"Armée"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"Désarmée"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"Modifier"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Supprimer"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"Supprimer la règle"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"Nom de la règle"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"ex. Chauffages éteints après impression"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"Si (déclencheur)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Alors (action)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"Chauffage"}},value:{t:0,b:{t:2,i:[{t:3}],s:"Température (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"Message"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Affiché dans le journal de la règle"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"ex. TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Enregistrer la règle"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annuler"}},add:{t:0,b:{t:2,i:[{t:3}],s:"Ajouter une règle"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"Activité récente"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"notifié"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"g-code exécuté"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"ignoré (imprimante occupée)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"erreur"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Guide"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Guide du moteur de règles"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Fermer"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Qu'est-ce que le moteur de règles ?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Il surveille l'imprimante et exécute une action lorsqu'une condition que vous avez définie est remplie - par exemple, enregistrer une note à la fin d'une impression, ou éteindre les chauffages. Chaque règle est SI (un déclencheur) ALORS (une action)."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Comment ça reste sûr"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Le moteur est désactivé par défaut et chaque règle doit être armée individuellement, donc rien ne s'exécute par surprise. Une règle se déclenche une fois lorsque sa condition devient vraie pour la première fois. Les actions g-code ne s'exécutent que lorsque l'imprimante est au repos - elles sont refusées pendant une impression - et chaque résultat est enregistré."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossaire"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"Déclencheur"}},def:{t:0,b:{t:2,i:[{t:3}],s:"La condition qui démarre une règle, ex. la fin d'une impression ou un chauffage franchissant une température."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"Action"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Ce que fait la règle quand elle se déclenche : enregistrer une notification, ou exécuter une commande g-code (uniquement au repos)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"Armée"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Une règle qui est activée. Les règles désarmées sont conservées mais ne se déclenchent jamais."}}}}}}};export{e as default};
